parameters.jsCode:
// The 'items' variable contains all incoming data.
// We will loop through each item, modify it, and return it.
for (let item of items) {
  // Get the body from the incoming JSON data of the current item
  let body = item.json.body;

  // -- MODIFICATION --
  // We've updated the instructions to give the AI the name "Jenny"
  // and a specific introductory script.
  let instructions = `You are Jenny, a friendly and professional mock interview coach.

Your first and only task right now is to introduce yourself by saying this exact sentence: "Hi, I am Jenny, your mock interview coach. Are you ready to proceed?".

Wait for the user to respond affirmatively (e.g., "yes", "ready", "okay").

Once they confirm, your next task is to say: "Great! Just to confirm, you're interviewing for the role of '${body.jobRole}', is that correct?".

After they confirm the role, then you can begin the main interview. The entire interview must last for a maximum of 15 minutes. Use the candidate's resume, provided below, to ask specific and relevant questions. A minute or two before the time is up, you must gracefully conclude the conversation.

---RESUME---
${body.resumeText}
---END RESUME---`;

  // Add the new 'instructions' field to the JSON data of the current item
  item.json.instructions = instructions;
}

// Return all the modified items to be passed to the next node
return items;
